package tr.kasaba.test;
import com.google.gson.*;import java.lang.reflect.*;import java.util.*;import java.nio.charset.StandardCharsets;
import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import org.bukkit.plugin.java.JavaPlugin;
import tr.kasaba.hub.api.*;
/** Loopback-only adapter. Never distributed. */
public final class BoyaProbe extends JavaPlugin implements org.bukkit.plugin.messaging.PluginMessageListener {
 Object game;final Gson json=new GsonBuilder().serializeNulls().create();
 public void onEnable(){if(!Bukkit.getIp().equals("127.0.0.1"))throw new IllegalStateException("Loopback only");game=Bukkit.getPluginManager().getPlugin("KasabaBoya");Bukkit.getMessenger().registerIncomingPluginChannel(this,"kasaba_test:boya",this);}
 public void onPluginMessageReceived(String channel,Player p,byte[] bytes){if(p.getAddress()==null||!p.getAddress().getAddress().isLoopbackAddress())return;String op=new String(bytes,StandardCharsets.UTF_8);Bukkit.getScheduler().runTask(this,()->{try{String[] a=op.split("\\|");Object room=((Map<?,?>)get(game,"membership")).get(p.getUniqueId());switch(a[0]){
 case "STATE"->{Map<String,Object>d=new LinkedHashMap<>();var hub=Bukkit.getServicesManager().load(HubApi.class);d.put("uuid",p.getUniqueId());d.put("world",p.getWorld().getName());d.put("location",List.of(p.getX(),p.getY(),p.getZ()));d.put("visitor",((Set<?>)get(game,"visitors")).contains(p.getUniqueId()));d.put("queued",((Set<?>)get(game,"queue")).contains(p.getUniqueId()));d.put("social",hub.socialArea(p.getUniqueId()));d.put("gameplay",hub.gameplay(p.getUniqueId()));d.put("rooms",((Map<?,?>)get(game,"rooms")).size());d.put("privateWorlds",Bukkit.getWorlds().stream().map(World::getName).filter(n->n.startsWith("boya_room_")).toList());d.put("items",Arrays.stream(p.getInventory().getContents()).map(i->i==null?"AIR":i.getType().name()+":"+i.getAmount()).toList());d.put("hp",p.getHealth());d.put("slow",p.hasPotionEffect(org.bukkit.potion.PotionEffectType.SLOWNESS));d.put("room",room==null?null:get(room,"id"));if(room!=null){d.put("phase",get(room,"phase"));d.put("practice",get(room,"practice"));d.put("teams",get(room,"teams"));d.put("shots",((Map<?,?>)get(room,"shots")).size());d.put("counts",get(get(room,"grid"),"counts"));d.put("painted",((Map<?,?>)get(get(room,"grid"),"owners")).size());d.put("bar",((org.bukkit.boss.BossBar)get(room,"bar")).getTitle());Object tile=cell(room);d.put("cell",List.of(call(tile,"x"),call(tile,"y"),call(tile,"z")));World w=(World)get(room,"world");int x=(int)call(tile,"x"),y=(int)call(tile,"y"),z=(int)call(tile,"z");d.put("cellType",w.getBlockAt(x,y,z).getType());World template=Bukkit.getWorld((String)get(get(room,"map"),"worldName"));d.put("templateCell",template.getBlockAt(x,y,z).getType());}say(p,"state:"+json.toJson(d));}
 case "AGEQUEUE"->{set(game,"queueDeadline",System.currentTimeMillis()-1);call(game,"tick");}
 case "TIMEOUT"->{set(room,"startedAt",System.currentTimeMillis()-601000);call(room,"tick",System.currentTimeMillis());}
 case "END"->{set(room,"finishAt",System.currentTimeMillis()-1);call(room,"tick",System.currentTimeMillis());}
 case "POSE"->{Object tile=cell(room);World w=(World)get(room,"world");Location at=new Location(w,(int)call(tile,"x")+.5,(int)call(tile,"y")+1,(int)call(tile,"z")+.5,0,90);call(game,"teleport",p,at);p.setRotation(0,90);p.getInventory().setHeldItemSlot(0);}
 case "PAIR"->{Player target=Bukkit.getPlayerExact(a[1]);Object tile=cell(room);World w=(World)get(room,"world");int x=(int)call(tile,"x"),y=(int)call(tile,"y"),z=(int)call(tile,"z");for(int xx=x;xx<=x+4;xx++)for(int yy=y+1;yy<=y+3;yy++)w.getBlockAt(xx,yy,z).setType(Material.AIR,false);call(game,"teleport",p,new Location(w,x+.5,y+1,z+.5,-90,0));call(game,"teleport",target,new Location(w,x+3.5,y+1,z+.5,90,0));p.setRotation(-90,0);p.getInventory().setHeldItemSlot(0);}
 case "RESET_CD"->((Map<?,?>)get(room,"lastShot")).remove(p.getUniqueId());
 case "IMPACT"->{call(room,"shoot",p);var shot=((Map<UUID,?>)get(room,"shots")).keySet().stream().findFirst().orElseThrow();var ball=(Projectile)Bukkit.getEntity(shot);Player target=Bukkit.getPlayerExact(a[1]);Bukkit.getPluginManager().callEvent(new ProjectileHitEvent(ball,target));ball.remove();}
 case "PAINT"->{Object tile=cell(room);Object own=((Map<?,?>)get(room,"teams")).get(p.getUniqueId());call(room,"splash",tile,own);}
 case "GUARDS"->{var breakEvent=new BlockBreakEvent(p.getLocation().clone().subtract(0,1,0).getBlock(),p);Bukkit.getPluginManager().callEvent(breakEvent);var damage=new EntityDamageEvent(p,EntityDamageEvent.DamageCause.FALL,5);Bukkit.getPluginManager().callEvent(damage);var gm=new PlayerGameModeChangeEvent(p,GameMode.CREATIVE);Bukkit.getPluginManager().callEvent(gm);var tp=new PlayerTeleportEvent(p,p.getLocation(),Bukkit.getWorlds().getFirst().getSpawnLocation());Bukkit.getPluginManager().callEvent(tp);var fly=new PlayerToggleFlightEvent(p,true);Bukkit.getPluginManager().callEvent(fly);var command=new PlayerCommandPreprocessEvent(p,"/give @s diamond");Bukkit.getPluginManager().callEvent(command);say(p,"guards:"+json.toJson(Map.of("break",breakEvent.isCancelled(),"damage",damage.isCancelled(),"mode",gm.isCancelled(),"teleport",tp.isCancelled(),"fly",fly.isCancelled(),"command",command.isCancelled())));}
 case "CLOSE_ALL"->{for(Object r:List.copyOf(((Map<?,?>)get(game,"rooms")).values()))call(r,"close");}
 default->throw new IllegalArgumentException(op);}
 say(p,"done:"+op);}catch(Throwable e){say(p,"error:"+e);getLogger().log(java.util.logging.Level.SEVERE,"Boya fixture",e);}});}
 Object cell(Object room)throws Exception{Object map=get(room,"map");List<Object> points=new ArrayList<>((Set<?>)get(map,"paintable"));World w=(World)get(room,"world");points.sort(Comparator.comparing(o->{try{return (int)call(o,"x")+1000*(int)call(o,"z");}catch(Exception e){throw new RuntimeException(e);}}));Set<String> keys=new HashSet<>();for(Object point:points)keys.add(call(point,"x")+","+call(point,"y")+","+call(point,"z"));for(Object point:points){int x=(int)call(point,"x"),y=(int)call(point,"y"),z=(int)call(point,"z");if(y!=79||Math.abs(x)>25||Math.abs(z)>15||!w.getBlockAt(x,y+1,z).isPassable()||!w.getBlockAt(x,y+2,z).isPassable())continue;boolean full=true;for(int xx=-2;xx<=2;xx++)for(int zz=-2;zz<=2;zz++)if(Math.abs(xx)+Math.abs(zz)<=2&&!keys.contains((x+xx)+","+y+","+(z+zz)))full=false;if(full)return point;}throw new IllegalStateException("No safe shot cell");}
 Object get(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 void set(Object target,String name,Object value)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);f.set(target,value);}
 Object call(Object target,String name,Object... args)throws Exception{Method m=Arrays.stream(target.getClass().getDeclaredMethods()).filter(x->x.getName().equals(name)&&x.getParameterCount()==args.length).findFirst().orElseThrow();m.setAccessible(true);return m.invoke(target,args);}
 void say(Player p,String text){p.sendMessage(net.kyori.adventure.text.Component.text("boya-probe:"+text));}
}
